 window.paisaRefresh=()=>{try{read();render();}catch(e){notice(e.message);}};window.paisaNotice=notice;window.paisaOpen=id=>{const e=data.entries.find(e=>e.id===id);if(e)e.pending||e.duplicateOf?review(e):edit(e);};window.paisaImportText=text=>{read();emailForm(text);};window.paisaBack=()=>{if($('sheet').open){close();return true;}if(page!=='home'){go('home');return true;}return false;};
